/// Abstraction over a readable, random-access file.
///
/// [`StorageReadService`] is generic over this trait so that the concrete file
/// backend can be swapped out; the production implementation is [`MmapFile`].
pub trait StorageFile: Sized {
    /// Open the file at `path` for reading.
    fn open(path: &Path) -> io::Result<Self>;

    /// Total length of the file in bytes.
    fn len(&self) -> u64;

    /// Read `length` bytes starting at `offset`.
    ///
    /// The caller must ensure that `offset + length <= len()`.
    fn read_range(&self, offset: u64, length: u64) -> io::Result<Vec<u8>>;
}

/// Memory-mapped file implementation of [`StorageFile`].
pub struct MmapFile {
    /// The memory map. `None` for empty files, which cannot be mapped.
    mmap: Option<memmap2::Mmap>,
    /// Length of the file in bytes.
    len: u64,
}

impl StorageFile for MmapFile {
    fn open(path: &Path) -> io::Result<Self> {
        let file = fs::File::open(path)?;
        let len = file.metadata()?.len();
        let mmap = if len == 0 {
            // Mapping a zero-length file is not allowed on all platforms.
            None
        } else {
            // SAFETY: the file is opened read-only and kept alive only for the
            // duration of the mapping's construction; the mapping is used as an
            // immutable byte slice.
            Some(unsafe { memmap2::Mmap::map(&file)? })
        };
        Ok(Self { mmap, len })
    }

    fn len(&self) -> u64 {
        self.len
    }

    fn read_range(&self, offset: u64, length: u64) -> io::Result<Vec<u8>> {
        if length == 0 {
            return Ok(Vec::new());
        }
        let start = offset as usize;
        let end = start + length as usize;
        match &self.mmap {
            Some(mmap) => Ok(mmap[start..end].to_vec()),
            // Only reachable for empty files, where `length` must be 0 (handled
            // above) for the range to be valid.
            None => Ok(Vec::new()),
        }
    }
}

