#[test]
fn mmap_file_reads() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("data.bin");
    let mut f = std::fs::File::create(&path).unwrap();
    f.write_all(&[1, 2, 3, 4, 5]).unwrap();
    drop(f);

    let mf = MmapFile::open(&path).unwrap();
    assert_eq!(mf.len(), 5);
    assert_eq!(mf.read_range(1, 3).unwrap(), vec![2, 3, 4]);
    assert_eq!(mf.read_range(0, 0).unwrap(), Vec::<u8>::new());

    // Empty file
    let empty = dir.path().join("empty.bin");
    std::fs::File::create(&empty).unwrap();
    let mfe = MmapFile::open(&empty).unwrap();
    assert_eq!(mfe.len(), 0);
    assert_eq!(mfe.read_range(0, 0).unwrap(), Vec::<u8>::new());
}

